public static ProblemDetailsHandler from(Config conf) {
    var handler = new ProblemDetailsHandler();
    if (conf.hasPath(ROOT_CONFIG_PATH)) {
        // PATH: Test should invoke the next Config.getConfig(...) [step in execution path]
        var problemConfig = conf.getConfig(ROOT_CONFIG_PATH);
        if (problemConfig.hasPath(LOG_4XX_ERRORS_KEY) && problemConfig.getBoolean(LOG_4XX_ERRORS_KEY)) {
            handler.log4xxErrors();
        }
        if (problemConfig.hasPath(MUTE_CODES_KEY)) {
            problemConfig.getIntList(MUTE_CODES_KEY).forEach(code -> handler.mute(StatusCode.valueOf(code)));
        }
        if (problemConfig.hasPath(MUTE_TYPES_KEY)) {
            var classLoader = ProblemDetailsHandler.class.getClassLoader();
            problemConfig.getStringList(MUTE_TYPES_KEY).forEach(throwingConsumer(className -> handler.mute(((Class<? extends Exception>) (classLoader.loadClass(className))))));
        }
    }
    return handler;
}

